private open class MessagesPigeonCodec : StandardMessageCodec() {
    override fun readValueOfType(
        type: Byte,
        buffer: ByteBuffer,
    ): Any? {
        return when (type) {
            129.toByte() -> {
                return (readValue(buffer) as Long?)?.let {
                    ScanSourceWire.ofRaw(it.toInt())
                }
            }

            130.toByte() -> {
                return (readValue(buffer) as Long?)?.let {
                    ImageOriginWire.ofRaw(it.toInt())
                }
            }

            131.toByte() -> {
                return (readValue(buffer) as Long?)?.let {
                    ScanStatusWire.ofRaw(it.toInt())
                }
            }

            132.toByte() -> {
                return (readValue(buffer) as Long?)?.let {
                    OcrModelStatusWire.ofRaw(it.toInt())
                }
            }

            133.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    ScanOptionsWire.fromList(it)
                }
            }

            134.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    GpsDataWire.fromList(it)
                }
            }

            135.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    ReceiptExifWire.fromList(it)
                }
            }

            136.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    OcrQualityWire.fromList(it)
                }
            }

            137.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    ReceiptImageWire.fromList(it)
                }
            }

            138.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    ScanResultWire.fromList(it)
                }
            }

            139.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    OcrLineWire.fromList(it)
                }
            }

            140.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    OcrModelStateWire.fromList(it)
                }
            }

            141.toByte() -> {
                return (readValue(buffer) as? List<Any?>)?.let {
                    OcrCapabilitiesWire.fromList(it)
                }
            }

            else -> {
                super.readValueOfType(type, buffer)
            }
        }
    }

    override fun writeValue(
        stream: ByteArrayOutputStream,
        value: Any?,
    ) {
        when (value) {
            is ScanSourceWire -> {
                stream.write(129)
                writeValue(stream, value.raw.toLong())
            }

            is ImageOriginWire -> {
                stream.write(130)
                writeValue(stream, value.raw.toLong())
            }

            is ScanStatusWire -> {
                stream.write(131)
                writeValue(stream, value.raw.toLong())
            }

            is OcrModelStatusWire -> {
                stream.write(132)
                writeValue(stream, value.raw.toLong())
            }

            is ScanOptionsWire -> {
                stream.write(133)
                writeValue(stream, value.toList())
            }

            is GpsDataWire -> {
                stream.write(134)
                writeValue(stream, value.toList())
            }

            is ReceiptExifWire -> {
                stream.write(135)
                writeValue(stream, value.toList())
            }

            is OcrQualityWire -> {
                stream.write(136)
                writeValue(stream, value.toList())
            }

            is ReceiptImageWire -> {
                stream.write(137)
                writeValue(stream, value.toList())
            }

            is ScanResultWire -> {
                stream.write(138)
                writeValue(stream, value.toList())
            }

            is OcrLineWire -> {
                stream.write(139)
                writeValue(stream, value.toList())
            }

            is OcrModelStateWire -> {
                stream.write(140)
                writeValue(stream, value.toList())
            }

            is OcrCapabilitiesWire -> {
                stream.write(141)
                writeValue(stream, value.toList())
            }

            else -> {
                super.writeValue(stream, value)
            }
        }
    }
}

