                val channel =
                    BasicMessageChannel<Any?>(
                        binaryMessenger,
                        "dev.flutter.pigeon.flutter_receipt_scanner.ReceiptScannerApi.scan$separatedMessageChannelSuffix",
                        codec,
                    )
                if (api != null) {
